<?php
declare(strict_types=1);
require_once __DIR__ . '/../PRACTICAL-10/session.php';
$user=sh_auth_user();
if($user===null){header('Location: ../PRACTICAL-02/login.php'.(!empty($_SESSION['session_expired'])?'?expired=1':''));exit;}
if(($user['role']??'')!=='admin'){header('Location: ../PRACTICAL-02/dashboard.php');exit;}
$csrf=sh_csrf_token();$db=studentHubMysqli();$errors=[];$notice='';
$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
function p11_bind(mysqli_stmt $s,string $types,array $values):void{if($types==='')return;$refs=[];foreach($values as $k=>&$v)$refs[$k]=&$v;$s->bind_param($types,...$refs);}
if(isset($_GET['notice'])){$messages=['created'=>'Student record added successfully.','updated'=>'Student record updated successfully.','deleted'=>'Student record permanently deleted.','inactive'=>'Student record deactivated.','restored'=>'Student record restored.'];$notice=$messages[(string)$_GET['notice']]??'';}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');
 if(!sh_valid_csrf($_POST['csrf_token']??null))$errors[]='Your session could not verify this request. Refresh and try again.';
 else try{
  if($action==='save'){
   $id=filter_var($_POST['student_id']??null,FILTER_VALIDATE_INT)?:0;$name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$mobile=trim((string)($_POST['mobile']??''));$program=trim((string)($_POST['program']??''));$year=filter_var($_POST['study_year']??null,FILTER_VALIDATE_INT);$gender=trim((string)($_POST['gender']??'prefer-not'));
   if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Name must contain 2 to 100 characters.';
   if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)$errors[]='Enter a valid email address.';
   if(!preg_match('/^[0-9]{10}$/',$mobile))$errors[]='Enter a 10-digit mobile number.';
   if($program===''||mb_strlen($program)>100)$errors[]='Enter a course/program (up to 100 characters).';
   if($year===false||$year<1||$year>4)$errors[]='Choose a study year from 1 to 4.';
   if(!in_array($gender,['female','male','other','prefer-not'],true))$errors[]='Choose a valid gender option.';
   if(!$errors){if($id>0){$s=$db->prepare('UPDATE students SET full_name=?,email=?,mobile=?,program=?,study_year=?,gender=? WHERE student_id=?');$s->bind_param('ssssisi',$name,$email,$mobile,$program,$year,$gender,$id);$s->execute();$s->close();header('Location: students.php?notice=updated');exit;}
    $s=$db->prepare('INSERT INTO students (full_name,email,mobile,program,study_year,gender) VALUES (?,?,?,?,?,?)');$s->bind_param('ssssis',$name,$email,$mobile,$program,$year,$gender);$s->execute();$s->close();header('Location: students.php?notice=created');exit;}
  }elseif(in_array($action,['delete','deactivate','restore'],true)){
   $id=filter_var($_POST['student_id']??null,FILTER_VALIDATE_INT)?:0;if($id<1)$errors[]='Choose a valid student record.';
   elseif($action==='delete'){$s=$db->prepare('DELETE FROM students WHERE student_id=?');$s->bind_param('i',$id);$s->execute();$affected=$s->affected_rows;$s->close();if($affected<1)$errors[]='Student record not found.';else{header('Location: students.php?notice=deleted');exit;}}
   else{$status=$action==='deactivate'?'inactive':'active';$s=$db->prepare('UPDATE students SET status=? WHERE student_id=?');$s->bind_param('si',$status,$id);$s->execute();$s->close();header('Location: students.php?notice='.($action==='deactivate'?'inactive':'restored'));exit;}
  }else $errors[]='Choose a valid student action.';
 }catch(mysqli_sql_exception $x){error_log('Practical 11 student management: '.$x->getMessage());if((int)$x->getCode()===1062)$errors[]='That email address already belongs to a student.';elseif((int)$x->getCode()===1451)$errors[]='This student has event registrations and cannot be permanently deleted. Deactivate the record instead.';else $errors[]='The database could not complete this request. Check setup and try again.';}
}
$q=trim((string)($_GET['q']??''));$programFilter=trim((string)($_GET['program']??''));$statusFilter=in_array($_GET['status']??'active',['active','inactive','all'],true)?(string)($_GET['status']??'active'):'active';$page=max(1,(int)($_GET['page']??1));$perPage=10;
$where=[];$types='';$params=[];if($q!==''){$where[]='(full_name LIKE ? OR email LIKE ? OR program LIKE ?)';$like='%'.$q.'%';$types.='sss';array_push($params,$like,$like,$like);}if($programFilter!==''){$where[]='program=?';$types.='s';$params[]=$programFilter;}if($statusFilter!=='all'){$where[]='status=?';$types.='s';$params[]=$statusFilter;}$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$programs=[];$students=[];$totalPages=1;$editStudent=null;
try{
 $r=$db->query('SELECT DISTINCT program FROM students ORDER BY program');while($row=$r->fetch_assoc())$programs[]=$row['program'];
 if(isset($_GET['edit'])){$editId=filter_var($_GET['edit'],FILTER_VALIDATE_INT)?:0;if($editId>0){$s=$db->prepare('SELECT student_id,full_name,email,mobile,program,study_year,gender FROM students WHERE student_id=?');$s->bind_param('i',$editId);$s->execute();$editStudent=$s->get_result()->fetch_assoc()?:null;$s->close();}}
 if(($_GET['export']??'')==='csv'){$s=$db->prepare('SELECT student_id,full_name,email,mobile,program,study_year,gender,status,created_at FROM students'.$whereSql.' ORDER BY full_name');p11_bind($s,$types,$params);$s->execute();$r=$s->get_result();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="studenthub-students.csv"');$out=fopen('php://output','w');fputcsv($out,['ID','Name','Email','Mobile','Course / Program','Year','Gender','Status','Created']);while($row=$r->fetch_assoc())fputcsv($out,$row);fclose($out);$s->close();exit;}
 $s=$db->prepare('SELECT COUNT(*) AS total FROM students'.$whereSql);p11_bind($s,$types,$params);$s->execute();$total=(int)$s->get_result()->fetch_assoc()['total'];$s->close();$totalPages=max(1,(int)ceil($total/$perPage));$page=min($page,$totalPages);$offset=($page-1)*$perPage;
 $s=$db->prepare('SELECT student_id,full_name,email,mobile,program,study_year,status FROM students'.$whereSql.' ORDER BY full_name LIMIT ?,?');p11_bind($s,$types.'ii',[...$params,$offset,$perPage]);$s->execute();$r=$s->get_result();while($row=$r->fetch_assoc())$students[]=$row;$s->close();
}catch(mysqli_sql_exception $x){error_log('Practical 11 student list: '.$x->getMessage());$errors[]='Student records could not be loaded. Import the Practical 11 SQL file and ensure MySQL is running.';}
$editId=(int)($_POST['student_id']??$editStudent['student_id']??0);$fn=(string)($_POST['full_name']??$editStudent['full_name']??'');$fe=(string)($_POST['email']??$editStudent['email']??'');$fm=(string)($_POST['mobile']??$editStudent['mobile']??'');$fp=(string)($_POST['program']??$editStudent['program']??'');$fy=(string)($_POST['study_year']??$editStudent['study_year']??'');$fg=(string)($_POST['gender']??$editStudent['gender']??'prefer-not');
function p11_url(array $replace=[]):string{return 'students.php?'.http_build_query(array_merge($_GET,$replace));}
