<?php if($notice!==''):?><p class="feedback success-message" role="status"><?= $e($notice) ?></p><?php endif;?><?php foreach($errors as $error):?><p class="feedback error-message" role="alert"><?= $e($error) ?></p><?php endforeach;?>
<form method="get" action="students.php"><div class="crud-toolbar"><div><label for="q">Search name, email, or course</label><input id="q" name="q" type="search" value="<?= $e($q) ?>" placeholder="e.g. Priya or Information Technology"></div><div><label for="program">Course / program</label><select id="program" name="program"><option value="">All courses</option><?php foreach($programs as $program):?><option value="<?= $e($program) ?>" <?= $programFilter===$program?'selected':'' ?>><?= $e($program) ?></option><?php endforeach;?></select></div><div><label for="status">Record status</label><select id="status" name="status"><option value="active" <?= $statusFilter==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $statusFilter==='inactive'?'selected':'' ?>>Inactive</option><option value="all" <?= $statusFilter==='all'?'selected':'' ?>>All records</option></select></div><div><button>Apply filters</button> <a class="button-link secondary" href="students.php">Reset</a></div></div></form>
<p><a class="button-link secondary" href="<?= $e(p11_url(['export'=>'csv','page'=>null])) ?>">Export filtered CSV</a></p><div class="table-wrap"><table><thead><tr><th>Student</th><th>Course / Year</th><th>Mobile</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php if(!$students):?><tr><td colspan="5">No students match these filters.</td></tr><?php endif;?><?php foreach($students as $s):?><tr><td><strong><?= $e($s['full_name']) ?></strong><small><?= $e($s['email']) ?> · #<?= (int)$s['student_id'] ?></small></td><td><?= $e($s['program']) ?><small>Year <?= (int)$s['study_year'] ?></small></td><td><?= $e($s['mobile']) ?></td><td><span class="status-pill"><?= ucfirst($e($s['status'])) ?></span></td><td><div class="row-actions"><a class="button-link secondary" href="students.php?<?= http_build_query(['edit'=>$s['student_id']]) ?>">Edit</a>
<form method="post" onsubmit="return confirm('<?= $s['status']==='active'?'Deactivate':'Restore' ?> this student record?')"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="student_id" value="<?= (int)$s['student_id'] ?>"><button class="secondary" name="action" value="<?= $s['status']==='active'?'deactivate':'restore' ?>"><?= $s['status']==='active'?'Deactivate':'Restore' ?></button></form>
<form method="post" onsubmit="return confirm('Permanently delete this student? Records with registrations cannot be deleted.')"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="student_id" value="<?= (int)$s['student_id'] ?>"><button class="danger" name="action" value="delete">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div>
<div class="pagination"><?php if($page>1):?><a href="<?= $e(p11_url(['page'=>$page-1])) ?>">← Previous</a><?php endif;?><span>Page <?= $page ?> of <?= $totalPages ?></span><?php if($page<$totalPages):?><a href="<?= $e(p11_url(['page'=>$page+1])) ?>">Next →</a><?php endif;?></div></section>
<section><h2><?= $editId?'Edit student':'Add a student' ?></h2><form method="post" action="students.php"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="student_id" value="<?= $editId ?>"><div class="form-grid"><div><label for="full_name">Full name</label><input id="full_name" name="full_name" maxlength="100" required value="<?= $e($fn) ?>"></div><div><label for="email">Email</label><input id="email" name="email" type="email" maxlength="190" required value="<?= $e($fe) ?>"></div><div><label for="mobile">Mobile number</label><input id="mobile" name="mobile" type="tel" pattern="[0-9]{10}" maxlength="10" required value="<?= $e($fm) ?>"></div><div><label for="program-input">Course / program</label><input id="program-input" name="program" maxlength="100" required value="<?= $e($fp) ?>" placeholder="B.Tech Information Technology"></div><div><label for="study_year">Study year</label><select id="study_year" name="study_year" required><option value="">Choose year</option><?php for($y=1;$y<=4;$y++):?><option value="<?= $y ?>" <?= (string)$y===$fy?'selected':'' ?>>Year <?= $y ?></option><?php endfor;?></select></div><div><label for="gender">Gender</label><select id="gender" name="gender"><option value="prefer-not" <?= $fg==='prefer-not'?'selected':'' ?>>Prefer not to say</option><option value="female" <?= $fg==='female'?'selected':'' ?>>Female</option><option value="male" <?= $fg==='male'?'selected':'' ?>>Male</option><option value="other" <?= $fg==='other'?'selected':'' ?>>Other</option></select></div></div><button><?= $editId?'Save changes':'Add student' ?></button><?php if($editId):?> <a class="button-link secondary" href="students.php">Cancel edit</a><?php endif;?></form></section></main>
